  // ASSETS · the ingestion tab. Two refusals that are NOT the same refusal (no
  // room = nowhere for the bytes to go; no ORCID = nobody to sign what is said
  // about them), and three sentences the app must never leave unsaid: a
  // supersession, where the gate is, and that a derivation is declared.
  "assets.needsIdentity": "The Assets tab needs an identity: attribution is an ACT and somebody signs it. Declare your ORCID iD in Settings ▸ Identity — it works offline — and come back.",
  "assets.needsDocument": "No document open: a file published with nothing to put it in would be bytes in a bucket. Open or create a graph first.",
  "assets.drop": "Drop files here — or drag them from the disk pane — and they go into «{room}» at once, each carrying the delivery above. One drop is one LOT: they arrive together, as one acquisition, and everything is refinable afterwards.",
  "assets.folderNotYet": "A whole folder at once is not in yet: open it on the left and drag the files.",
  "assets.queued": "{n} in the queue",
  "assets.fromShelf": "Take the {n} from the shelf",
  "assets.fromShelfHint": "The shelf already holds the files you chose from the disk, with the digest the bridge computed. Only one Files surface is mounted at a time, so dragging from the pane on the left into this one is not a gesture that exists yet — this is the way in for a file on disk.",
  "assets.lot": "Name of the lot",
  "assets.lotPlaceholder": "Flight 2026-03, Trench II photos…",
  "assets.lotHint": "Worth typing. An unnamed lot is still ONE lot — this delivery mints its own id — but the corpus labels it the moment the first file lands, so a lot of three hundred photographs ends up reading «Acquisition of 1 file(s)». A name replaces that, and dropping more files under the same name joins them to it.",
  "assets.license": "Licence",
  "assets.licenseHint": "Said once, for the whole lot. Every file reads it through the chain — it is not copied onto each of them, because a copy is a thing that can disagree.",
  "assets.author": "Author (who made it)",
  "assets.authorPlaceholder": "name and surname",
  "assets.authorHint": "Who made these bytes — possibly somebody who is not here. YOU are the attributor, and that is recorded separately: the act is signed with your iD.",
  "assets.orcidBad": "Not a valid ORCID ({problem}) — not written.",
  "assets.residencyLabel": "Where the bytes live",
  "assets.residency.resident": "resident (in the room's store)",
  "assets.residency.reference": "reference (they stay where they are)",
  "assets.residentNote": "The bytes go into the room's object store: StratiGraph Server is in their path, so the embargo gate and the licence header apply to them.",
  "assets.referenceNote": "HONEST NOTE: bytes by reference stay outside StratiGraph Server, so NO embargo can be applied to them and the licence can only travel, not be enforced. Never use it for sensitive or embargoed material. It needs a path — a file dropped from the desktop has no location the graph could point at.",
  "assets.referenceNeedsPath": "reference needs a file from the disk pane: a desktop drop has no path, and a reference to nowhere is not a reference.",
  "assets.scope": "Fence (where it comes from)",
  "assets.scopeHint": "own-study = mine; own-HDT = from a twin of my own (of the site, a building, a unit…); other-HDT = from somebody else's twin, a comparandum. It changes what a comparison means, so it is recorded.",
  "assets.queue": "Queue ({n})",
  "assets.queueEmpty": "Nothing queued. Drop files above, or pick them.",
  "assets.use.iiif": "image (IIIF/annotation)",
  "assets.use.proxy": "3D (proxy/model)",
  "assets.use.document": "document (source)",
  "assets.use.evidence": "evidence (embed)",
  "assets.use.raw": "raw material",
  "assets.useHint": "Deduced from the format. It is a DECISION, not a fact about the bytes — correct it here if this image is a source to read rather than a picture to annotate.",
