  "assets.openInspector": "Double-click: select the resource and read it in the Inspector",
  "assets.publish": "Publish {n} file(s)",
  "assets.publishHint": "Bytes first, then the graph: a crash leaves an orphan object in the store rather than a graph pointing at nothing.",
  "assets.clearDone": "Clear what is done",
  "assets.superseded": "«{name}» is already in the graph with DIFFERENT bytes, and {n} node(s) cite it. The old one is not replaced: decide which the study should point at — a superseded asset may no longer be what a published text cites.",
  "assets.supersedes": "replaces? {n} citations",
  "assets.bucketed": "{n} file(s) in the lot «{lot}», with its licence and its author",
  // I2 · niente entra nello store senza un verbale
  "assets.stampTravelled": "«{name}» arrived with its own stamp: it travelled to the store unchanged",
  "assets.stampNotTravelled": "«{name}»: the bytes are in the store and its stamp is NOT — say so before citing it",
  "assets.stampMismatch": "«{name}» has a stamp beside it that describes OTHER bytes. It is not broken and it was not reused: a file re-exported over its own name gets a new identity, and the old record is a true statement about something else.",
  "assets.ingestionStamped": "«{name}» carried no stamp: the ingestion itself is on record — who put it here, and when",
  "assets.stampFailed": "no ingestion record was written: {detail}. The bytes are in the store and nothing says who put them there.",
  "assets.stampNeedsIdentity": "no identity: nothing was stamped rather than stamping in nobody's name",
  "assets.hintWritten": "«{name}»: where it landed is noted as a hint — the stamp is untouched",
  "assets.poorProvenance": "Ingestion record",
  "assets.poorProvenanceHint": "No parents and nothing about how these bytes were made — because nobody declared it. It says only that this thing came in here, by this hand, at this moment.",
  "assets.stampedOwn": "Stamped at the source",
  "assets.lots": "Lots in this graph",
  "assets.corpus": "Documentation (the DTC corpus)",
  "assets.delivery": "The delivery — signed before dragging",
  "assets.depositor": "Depositor",
  "assets.depositorHint": "Not a field: it comes from your token, and the server takes the attributor from there. There is nowhere here to type a name that is not yours.",
  "assets.editor": "Editor",
  "assets.editorMe": "me — {who}",
  "assets.editorMeHint": "Whoever answers for having published this. Recorded already: it is the attributor of every statement in this delivery.",
  "assets.editorOther": "somebody else",
  "assets.editorName": "The editor",
  "assets.editorPlaceholder": "who answers for publishing this",
  "assets.editorNotYet": "The acts carry the AUTHOR (who made it) and the ATTRIBUTOR (who says so, from your token) and nothing else — an editor who is not you has no place in the register yet. Writing it into a metadata bag would look recorded and would never be read. Say «me», or wait for the field.",
  "assets.authorIsMe": "It was me",
  "assets.authorIsMeHint": "Fills the author with your own identity. A click, on purpose: a pre-filled author asserts that whoever is logged in made the files, and one often deposits what a colleague made.",
  "assets.licensePlaceholder": "required — no licence is chosen for you",
  "assets.licenseOffer": "Use {license}",
  "assets.licenseOfferHint": "What StratiGraph publishes under when somebody chooses it. Offered, never preselected: a licence nobody picked is a legal statement nobody made.",
  "assets.needsLicense": "Choose a licence: the delivery is not signed without one, and a preselected licence would be a statement nobody made.",
  "assets.embargo": "Embargo until",
  "assets.embargoHint": "Optional. While it runs, the bytes are for the people working on them — editor and above — and everyone else is told the date rather than that the file does not exist.",
  "assets.embargoReason": "Why",
  "assets.embargoReasonPlaceholder": "why these bytes wait",
  "assets.deliverySigned": "Signed — every file that lands inherits this.",
  "assets.debt": "{stored} deposited, {signed} signed.",
  "assets.debtHint": "{n} files are in the store with nothing said about who made them or what may be done with them. This count does not go away when you clear the list.",
