  "insp.lotRights": "Diritti di questo lotto (DTC)",
  "insp.resourceRights": "Diritti di questa risorsa (DTC)",
  "insp.lotRightsHint": "Vale per TUTTI i file del lotto: ognuno legge questa licenza risalendo la catena, e chi ne ha una propria vince (la frase più specifica è quella detta su quell'oggetto). Vuoto = non dichiarato.",
  "insp.resourceRightsHint": "Vale per i BYTE: finché l'embargo corre il server serve il file solo a chi lavora allo studio (editor in su), e la licenza viaggia con il download. Vuoto = non dichiarato (allora vale il default del grafo).",
