  // ── HDT-O · l'attribuzione e i suoi tre stati ─────────────────────────────
  "insp.hdt": "Lo studio, il suo luogo, il suo bene",
  "insp.hdtHint":
    "Ogni studio ha un luogo — il sito, scritto una volta, ed è questo che rende trovabili insieme otto campagne in un sito. Un bene patrimoniale è un passo in più, da fare solo quando il patrimonio è riconosciuto: dargli un nome permette agli altri di trovare il tuo lavoro accanto al loro. Non saperlo ancora è normale: lascia stare, continua a scavare, e dillo più avanti.",
  "insp.hdtStudy": "Questo studio",
  "insp.hdtStudyGloss": "HC9 · Study — la campagna, la stagione, il lavoro che questo grafo registra.",
  "insp.hdtStudyTitle": "Titolo",
  "insp.hdtStudyTitlePh": "es. Aiano, campagna 2026",
  "insp.hdtStudyAuthors": "Autore/i",
  "insp.hdtStudyAuthorsPh": "es. Rossi, Bianchi",
  "insp.hdtStudyDate": "Data",
  "insp.hdtStudyDatePh": "es. 2026",
  "insp.hdtEntity": "La cosa nel mondo",
  "insp.hdtEntityGloss": "HC1 · Heritage entity — il monumento, il sito o il paesaggio in sé, distinto da qualunque sua registrazione digitale.",
  "insp.hdtEntityName": "Nome",
  "insp.hdtEntityNamePh": "il bene riconosciuto, es. Colosseo",
  "insp.hdtParent": "Parte di",
  "insp.hdtParentPh": "l'insieme a cui appartiene, es. Poggibonsi",
  "insp.hdtTwin": "Il suo gemello digitale",
  "insp.hdtTwinGloss": "HC2 · Heritage Digital Twin — la registrazione digitale condivisa di quella cosa, a cui più studi possono appendersi. Un gemello è il gemello di un bene a qualunque scala: un sito, un edificio, una sola unità (un'iscrizione, US 100) possono avere ciascuno il suo; questo grafo è uno degli insiemi di proposizioni (HC16) che raccoglie.",
  "insp.hdtProject": "Il progetto",
  "insp.hdtProjectGloss": "HC13 · Project — la cornice finanziata o istituzionale in cui lo studio è stato fatto.",
  "insp.hdtProjectName": "Nome",
  "insp.hdtProjectNamePh": "facoltativo",
  "insp.hdtProjectHint":
    "Testo libero, e per scelta: gli authority file dietro ai campi qui sopra rispondono a «dove», «quando», «di che tipo» e «chi», e un progetto di ricerca non è nessuna di queste cose. Agganciarlo alla faccetta più vicina lo farebbe SEMBRARE risolto. Un registro dei progetti (CORDIS, ROR, il DOI di un grant) ha bisogno prima di una faccetta sua.",
  "insp.authority": "Authority",
  "insp.authorityPlaceholder": "scrivi per cercare in un authority file, o incolla una URI",
  "insp.authorityOffline": "Resolver offline: scrivi un termine, scegli una corrispondenza, o incolla una URI.",
  "insp.authorityNoResolver": "Incolla una URI di authority (resolver non disponibile).",
  "insp.authorityUnresolved": "Testo libero — non risolto su un authority file.",
  "insp.twinStateNone": "Non ancora attribuito",
  "insp.twinStateNoneHint":
    "Stai scavando e non sai ancora a cosa pertiene. È uno stato, non una casella vuota: niente di quanto segue deve essere compilato perché il resto dello studio funzioni.",
  "insp.twinStateProvisional": "Gemello provvisorio",
  "insp.twinStateProvisionalHint":
    "Te lo sei creato tu, perché ti serviva un posto dove mettere quello che stai trovando — cosa normalissima. Vive solo in questo documento; alla pubblicazione si potrà dire che è nuovo, oppure riconoscere che è quello di qualcun altro.",
  "insp.twinStateRegistered": "Gemello registrato",
  "insp.twinStateRegisteredHint":
    "Lo conosce un registro ({registry}), quindi gli altri lo trovano e le loro campagne si leggono accanto alla tua.",
  "insp.twinName": "Nome del gemello",
  "insp.twinNamePh": "es. Villa di Aiano HDT",
  "insp.twinKey": "Identità condivisa",
  "insp.twinDetach": "Non è questo",
  "insp.twinDetachTitle": "Stacca il gemello da questo studio. Non cancella nient'altro: lo studio, l'entità e il grafo restano esattamente come sono.",
  "insp.twinNeedsEntity":
    "Prima dai un nome alla cosa, anche approssimativo — un gemello è il gemello DI qualcosa, quindi «un edificio senza nome sotto il campo nord» basta e avanza per cominciare.",
  "insp.twinCreate": "Crea un gemello provvisorio",
  "insp.twinCreateTitle": "Un posto tuo dove mettere quello che stai trovando. Si potrà pubblicare più avanti, e fondere con un gemello esistente se si rivelerà la stessa cosa.",
