  "assets.fromShelfHint": "Lo scaffale contiene già i file che hai scelto dal disco, col checksum calcolato dal bridge. Una sola superficie File è montata alla volta, quindi trascinare dal riquadro di sinistra a questo non è ancora un gesto che esiste: questa è la via d'ingresso per un file su disco.",
  "assets.lot": "Nome del lotto",
  "assets.lotPlaceholder": "Volo 2026-03, foto Saggio II…",
  "assets.lotHint": "Conviene scriverlo. Un lotto senza nome è comunque UN lotto — questa consegna si fa il suo id — ma il corpus lo etichetta appena atterra il primo file, quindi un lotto di trecento foto finisce per leggersi «Acquisition of 1 file(s)». Un nome lo sostituisce, e trascinando altri file con lo stesso nome si aggiungono a quello.",
  "assets.license": "Licenza",
  "assets.licenseHint": "Detta una volta, per tutto il lotto. Ogni file la legge risalendo la catena — non viene copiata su ognuno, perché una copia è una cosa che può discordare.",
  "assets.author": "Autore (chi l'ha fatto)",
  "assets.authorPlaceholder": "nome e cognome",
  "assets.authorHint": "Chi ha prodotto questi byte — anche una persona che non è qui. L'attributore sei TU, e resta scritto a parte: l'atto è firmato col tuo iD.",
  "assets.orcidBad": "ORCID non valido ({problem}) — non l'ho scritto.",
  "assets.residencyLabel": "Dove stanno i byte",
  "assets.residency.resident": "resident (nello store della stanza)",
  "assets.residency.reference": "reference (restano dove sono)",
  "assets.residentNote": "I byte entrano nell'object store della stanza: StratiGraph Server è sul loro percorso, quindi il cancello dell'embargo e l'header della licenza valgono per loro.",
  "assets.referenceNote": "NOTA ONESTA: i byte by reference stanno FUORI da StratiGraph Server, quindi NESSUN embargo può essere applicato e la licenza può solo viaggiare, non essere imposta. Mai per materiale sensibile o embargato. Serve un percorso: un file trascinato dal desktop non ha una posizione che il grafo possa indicare.",
  "assets.referenceNeedsPath": "reference vuole un file dal riquadro del disco: un drop dal desktop non ha percorso, e un riferimento a nulla non è un riferimento.",
  "assets.scope": "Recinto (da dove viene)",
  "assets.scopeHint": "own-study = mio; own-HDT = da un mio gemello (del sito, di un edificio, di un'unità…); other-HDT = dal gemello di qualcun altro, un comparandum. Cambia il senso di un confronto, quindi si scrive.",
  "assets.queue": "Coda ({n})",
