  "assets.editorName": "L'editore",
  "assets.editorPlaceholder": "chi risponde di questa pubblicazione",
  "assets.editorNotYet": "Gli atti portano l'AUTORE (chi l'ha fatto) e l'ATTRIBUTORE (chi lo dice, dal tuo token), e nient'altro — un editore che non sei tu non ha ancora posto nel registro. Scriverlo in un sacchetto di metadati sembrerebbe registrato e non verrebbe mai letto. Metti «io», o aspetta il campo.",
  "assets.authorIsMe": "Sono io",
  "assets.authorIsMeHint": "Mette la tua identità come autore. Un clic, di proposito: un autore precompilato afferma che chi è connesso ha FATTO i file, e spesso si deposita quel che ha fatto un collega.",
